</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    static class Edge implements Comparable<Edge> {
        int diff;
        int index;

        Edge(int diff, int index) {
            this.diff = diff;
            this.index = index;
        }

        public int compareTo(Edge o) {
            int cmp = diff - o.diff;
            if (cmp != 0) return cmp;
            return index - o.index;
        }
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream byteBuffer = new ByteArrayOutputStream();
        byte[] buf = new byte[4096];
        int read;
        InputStream in = System.in;
        while ((read = in.read(buf)) != -1) {
            byteBuffer.write(buf, 0, read);
        }

        String[] tokens = byteBuffer.toString("UTF-8").trim().split("\\s+");
        int pos = 0;
        int n = Integer.parseInt(tokens[pos++]);
        int k = Integer.parseInt(tokens[pos++]);

        int[] a = new int[n];
        int[] odd = new int[n];
        int balance = 0;
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(tokens[pos++]);
            balance += (a[i] & 1) == 0 ? 1 : -1;
            odd[i] = balance;
        }

        Edge[] edges = new Edge[n - 1];
        for (int i = 0; i + 1 < n; i++) {
            edges[i] = new Edge(Math.abs(a[i + 1] - a[i]), i);
        }

        Arrays.sort(edges);

        int ans = 0;
        for (Edge e : edges) {
            if (k >= e.diff && odd[e.index] == 0) {
                int nk = k - e.diff;
                if (nk >= 0) {
                    ans++;
                    k = nk;
                }
            }
        }
        System.out.println(ans);
    }
}
